const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define location and dates
  const location = ee.Geometry.Point([-87.160422, 56.271030]);
  const date1 = '2020-07-13';
  const date2 = '2020-07-29';

  // Create buffers around the point (5km radius for local analysis)
  const geometry = location.buffer(5000);

  // Acquire Sentinel-1 SAR data (better for ice detection through clouds)
  const s1_date1 = ee.ImageCollection('COPERNICUS/S1_GRD')
    .filterBounds(geometry)
    .filterDate(date1, ee.Date(date1).advance(1, 'day'))
    .filter(ee.Filter.eq('instrumentMode', 'IW'));

  const s1_date2 = ee.ImageCollection('COPERNICUS/S1_GRD')
    .filterBounds(geometry)
    .filterDate(date2, ee.Date(date2).advance(1, 'day'))
    .filter(ee.Filter.eq('instrumentMode', 'IW'));

  const size1 = s1_date1.size().getInfo();
  const size2 = s1_date2.size().getInfo();

  print("July 13, 2020 S1 images: " + size1);
  print("July 29, 2020 S1 images: " + size2);

  // Check if data exists
  if (size1 === 0 || size2 === 0) {
    print("Attempting Landsat 8 fallback...");

    const ls8_date1 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(geometry)
      .filterDate(date1, ee.Date(date1).advance(1, 'day'))
      .map(function(img) {
        const qa = img.select('QA_PIXEL');
        const cloudMask = qa.bitwiseAnd(1 << 3).eq(0).and(qa.bitwiseAnd(1 << 4).eq(0));
        return img.updateMask(cloudMask);
      });

    const ls8_date2 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(geometry)
      .filterDate(date2, ee.Date(date2).advance(1, 'day'))
      .map(function(img) {
        const qa = img.select('QA_PIXEL');
        const cloudMask = qa.bitwiseAnd(1 << 3).eq(0).and(qa.bitwiseAnd(1 << 4).eq(0));
        return img.updateMask(cloudMask);
      });

    const ls_size1 = ls8_date1.size().getInfo();
    const ls_size2 = ls8_date2.size().getInfo();

    print("Landsat July 13: " + ls_size1);
    print("Landsat July 29: " + ls_size2);

    if (ls_size1 === 0 || ls_size2 === 0) {
      print("<answer>C1</answer>");
      return;
    }
  }

  // Use Sentinel-1 median composite for ice detection (VV band shows ice as bright)
  let img1, img2;

  if (size1 > 0 && size2 > 0) {
    img1 = s1_date1.median();
    img2 = s1_date2.median();

    // Ice detection: high VV backscatter (dB values > -10)
    const ice1 = img1.select('VV').gt(-10);
    const ice2 = img2.select('VV').gt(-10);

    const iceCount1 = ice1.reduceRegion(
      {reducer: ee.Reducer.count(), geometry: geometry, scale: 1000, maxPixels: 1e9}
    ).get('VV').getInfo();

    const iceCount2 = ice2.reduceRegion(
      {reducer: ee.Reducer.count(), geometry: geometry, scale: 1000, maxPixels: 1e9}
    ).get('VV').getInfo();

    print("Ice pixels July 13: " + iceCount1);
    print("Ice pixels July 29: " + iceCount2);

    if (iceCount1 === null || iceCount2 === null || iceCount1 === 0 || iceCount2 === 0) {
      print("<answer>C2</answer>");
      return;
    }

    // Compare ice extent
    if (iceCount2 > iceCount1) {
      print("More ice on July 29 (" + iceCount2 + " vs " + iceCount1 + ")");
      print("<answer>A</answer>");
    } else {
      print("Less or equal ice on July 29 (" + iceCount2 + " vs " + iceCount1 + ")");
      print("<answer>B</answer>");
    }
  } else {
    print("<answer>C1</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
